import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.DY3PNiwX.js";const u=JSON.parse('{"title":"Protocol contract","description":"The public contract for this SDK release. The wire types in @chainsafe/x402-core are the machine-readable source.","frontmatter":{"description":"The public contract for this SDK release. The wire types in @chainsafe/x402-core are the machine-readable source."},"headers":[],"relativePath":"protocol/spec.md","filePath":"protocol/spec.md"}'),n={name:"protocol/spec.md"};function o(r,e,c,d,h,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="protocol-contract" tabindex="-1">Protocol contract <a class="header-anchor" href="#protocol-contract" aria-label="Permalink to &quot;Protocol contract&quot;">​</a></h1><p>This is the contract this SDK release implements. The machine-readable source is the schemas in <code>@chainsafe/x402-core</code>. Field-level request and response tables are in the <a href="/canton-x402-sdk/pr-144/api-reference.html">API reference</a>. A facilitator backend may still change how it reaches a verdict. It does not change the verdicts, headers, or retry rule below.</p><h2 id="one-paid-call" tabindex="-1">One paid call <a class="header-anchor" href="#one-paid-call" aria-label="Permalink to &quot;One paid call&quot;">​</a></h2><ol><li>The resource server answers an unpaid request with <code>402</code> and <code>PAYMENT-REQUIRED</code>: <code>{ x402Version: 2, resource, accepts }</code>.</li><li>The payer chooses one <code>accepts[]</code> entry, prepares a Canton transfer, and signs its hash. The private key stays with the payer.</li><li>The retry carries that payment in <code>PAYMENT-SIGNATURE</code>. <code>X-PAYMENT</code> is still read when <code>PAYMENT-SIGNATURE</code> is absent, for a payment of this shape.</li><li>The merchant checks the echoed requirements against its own terms, then calls <code>POST /v2/verify</code> and, when configured to capture, <code>POST /v2/settle</code>.</li><li>A successful settle returns the Canton update id. The merchant puts that answer in <code>PAYMENT-RESPONSE</code> and serves the resource.</li></ol><p><code>createX402Fetch</code> performs steps 2 and 3 for a challenge that contains <code>PAYMENT-REQUIRED</code>.</p><h2 id="what-the-facilitator-owns" tabindex="-1">What the facilitator owns <a class="header-anchor" href="#what-the-facilitator-owns" aria-label="Permalink to &quot;What the facilitator owns&quot;">​</a></h2><p><code>GET /v2/supported</code> is the source for the instrument registry admin, the synchronizer, and <code>feePayer</code>. Express reads them when it quotes. A merchant spec names the instrument id (<code>asset: &quot;Amulet&quot;</code>) and may name <code>network</code> to choose a deployment. It cannot set the admin, <code>synchronizerId</code>, or <code>feePayer</code>. Naming <code>network</code> does not skip discovery.</p><p>A builder that writes those <code>extra</code> fields itself is checked against <code>/v2/supported</code> before the 402 is issued. A mismatch is a <code>TermsError</code>.</p><p>See <a href="/canton-x402-sdk/pr-144/upgrading.html">Upgrading</a> if a merchant config still sets them.</p><h2 id="verdicts-are-http-200" tabindex="-1">Verdicts are HTTP 200 <a class="header-anchor" href="#verdicts-are-http-200" aria-label="Permalink to &quot;Verdicts are HTTP 200&quot;">​</a></h2><p><code>/v2/verify</code> and <code>/v2/settle</code> return an evaluated payment outcome with HTTP 200, including <code>{ isValid: false }</code> and <code>{ success: false }</code>. <code>FacilitatorClient</code> returns those as <code>VerifyResponse</code> and <code>SettleResponse</code>.</p><p>HTTP 400, 401, 429, 500, and 503 are protocol or transport failures. <code>FacilitatorClient</code> throws <code>FacilitatorError</code> for any non-2xx response. A 400 is not a payment verdict and must not be retried as one.</p><h2 id="settlement-pending" tabindex="-1"><code>settlement_pending</code> <a class="header-anchor" href="#settlement-pending" aria-label="Permalink to &quot;\`settlement_pending\`&quot;">​</a></h2><p>The signed transaction was submitted and the ledger outcome is not known. This is not a failure and not a reason to sign a second transfer.</p><p>Verify returns it when a retry reaches a transaction the facilitator has already seen:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;isValid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;invalidReason&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;settlement_pending&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;extensions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;submission_replayed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;extra&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;transaction&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;preparedTxHash&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;network&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;canton:devnet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Settle returns it on the settle body itself. There, <code>transaction</code> is also the <code>preparedTxHash</code>. On a successful settle, <code>transaction</code> is the Canton update id. Read the reason code before interpreting <code>transaction</code>.</p><p>Express answers either case with <code>402</code> and <code>PAYMENT-RESPONSE</code> only. It does not send <code>PAYMENT-REQUIRED</code>, does not serve the route, and does not call <code>onReject</code>. A pending verify answer that omits <code>extra.transaction</code> or <code>extra.network</code> is an ordinary refusal, because the buyer would have nothing to resend.</p><p><code>createX402Fetch</code> returns that pending 402 without signing again. A later call starts from an unpaid request, receives a new challenge, and would sign a new transfer. To stay on the first payment, resend the original <code>PAYMENT-SIGNATURE</code>.</p>`,19)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
